// ---------- git helpers continued ----------
fn find_repo(input: Option<&str>) -> PathBuf {
    let input_str = input.unwrap_or(".");
    let p = Path::new(input_str);
    // check exists and is dir
    match std::fs::metadata(p) {
        Ok(m) => {
            if !m.is_dir() {
                eprintln!("Error: Failed to access a directory, or path is not a directory: '{}'", input_str);
                std::process::exit(1);
            }
        }
        Err(_) => {
            eprintln!("Error: Failed to access a directory, or path is not a directory: '{}'", input_str);
            std::process::exit(1);
        }
    }
    // try git rev-parse --show-toplevel
    let out = ProcCommand::new("git").args(["rev-parse", "--show-toplevel"]).current_dir(p).output();
    if let Ok(o) = out {
        if o.status.success() {
            let s = String::from_utf8_lossy(&o.stdout).trim().to_string();
            return PathBuf::from(s);
        }
    }
    eprintln!("Error: Could not find a git repository in '{}' or in any of its parents", input_str);
    std::process::exit(1);
}

