    let e = email.ok().and_then(|o| if o.status.success() { Some(String::from_utf8_lossy(&o.stdout).trim().to_string()) } else { None }).unwrap_or_default();
    if !n.is_empty() && !e.is_empty() {
        n
    } else {
        String::new()
    }
}

fn get_head(repo: &Path) -> (String, Vec<String>) {
