                String::from_utf8_lossy(&o.stdout).trim().to_string()
            } else {
                "refs/heads/main".to_string()
            }
        } else {
            "refs/heads/main".to_string()
        };
        // branch is like refs/heads/main
        eprintln!("Error: Failed to traverse Git commit history\n\nCaused by:\n    Branch '{}' does not have any commits", branch);
        std::process::exit(1);
    }
    let short = run_git_stdout(&["rev-parse", "--short", "HEAD"], repo).unwrap_or_default().trim().to_string();
    let abbrev = run_git_stdout(&["rev-parse", "--abbrev-ref", "HEAD"], repo).unwrap_or_default().trim().to_string();
    if abbrev == "HEAD" || abbrev.is_empty() {
        return (short, vec![]);
    }
    let mut refs = vec![abbrev.clone()];
    // upstream
    let up_out = ProcCommand::new("git").args(["rev-parse", "--abbrev-ref", "--symbolic-full-name", "@{u}"]).current_dir(repo).output();
