fn get_manifests(repo: &Path) -> (Option<(String,String,String,usize)>, Option<(String,String,String,usize)>) {
    // returns (cargo_info, npm_info) where each is (version, description, license, dep_count) ??? Actually description Option, version String, etc.
    // We'll return separate structs? Simplify: return (cargo_valid, cargo_version, cargo_desc, cargo_license, cargo_deps, npm_valid, ...)
    // For now, parse here and return tuple of Options
    // Cargo
    let cargo_path = repo.join("Cargo.toml");
    let mut cargo_opt: Option<(String, Option<String>, String, usize)> = None;
    if cargo_path.is_file() {
        if let Ok(content) = std::fs::read_to_string(&cargo_path) {
            if let Ok(toml_val) = content.parse::<toml::Value>() {
                if let Some(pkg) = toml_val.get("package") {
                    if let Some(name) = pkg.get("name").and_then(|v| v.as_str()) {
                        if !name.is_empty() {
                            // valid (requires name)
                            let version = pkg.get("version").and_then(|v| v.as_str()).unwrap_or("0.0.0").to_string();
                            let desc = pkg.get("description").and_then(|v| v.as_str()).map(|s| s.to_string());
                            let lic = pkg.get("license").and_then(|v| v.as_str()).unwrap_or("").to_string();
                            let deps = toml_val.get("dependencies").and_then(|v| v.as_table()).map(|t| t.len()).unwrap_or(0);
                            cargo_opt = Some((version, desc, lic, deps));
                        }
                    }
                }
            }
        }
    }
    // Npm
    let npm_path = repo.join("package.json");
    let mut npm_opt: Option<(String, Option<String>, String, usize)> = None;
    if npm_path.is_file() {
        if let Ok(content) = std::fs::read_to_string(&npm_path) {
            if let Ok(json_val) = serde_json::from_str::<serde_json::Value>(&content) {
                if let (Some(name), Some(version)) = (json_val.get("name").and_then(|v| v.as_str()), json_val.get("version").and_then(|v| v.as_str())) {
                    if !name.is_empty() && !version.is_empty() {
                        let desc = json_val.get("description").and_then(|v| v.as_str()).map(|s| s.to_string());
                        let lic = json_val.get("license").and_then(|v| v.as_str()).unwrap_or("").to_string();
                        let deps = json_val.get("dependencies").and_then(|v| v.as_object()).map(|o| o.len()).unwrap_or(0);
                        npm_opt = Some((version.to_string(), desc, lic, deps));
                    }
                }
            }
        }
    }
    (cargo_opt, npm_opt)
}

fn get_version_string(repo: &Path, tags: &[String]) -> String {
    if !tags.is_empty() {
        let mut sorted = tags.to_vec();
        sorted.sort();
        return sorted[0].clone();
    }
    let (cargo_opt, npm_opt) = get_manifests(repo);
    if let Some((ver, _, _, _)) = cargo_opt {
        return ver;
    }
    if let Some((ver, _, _, _)) = npm_opt {
        return ver;
    }
    String::new()
}

fn get_description(repo: &Path) -> Option<String> {
    let (cargo_opt, npm_opt) = get_manifests(repo);
    if let Some((_, desc, _, _)) = cargo_opt {
        return desc;
    }
    if let Some((_, desc, _, _)) = npm_opt {
        return desc;
    }
    None
}

fn get_dependencies(repo: &Path) -> String {
    let (cargo_opt, npm_opt) = get_manifests(repo);
    if let Some((_, _, _, deps)) = cargo_opt {
        if deps > 0 {
            return format!("{} (Cargo)", deps);
        } else {
            return String::new();
        }
    }
    if let Some((_, _, _, deps)) = npm_opt {
        if deps > 0 {
            return format!("{} (Npm)", deps);
        } else {
