        }
    }
    String::new()
}

fn detect_license_text(content: &str) -> Option<String> {
    // Very simple askalono-like for MIT, Apache, GPL, BSD, etc.
    // For MIT: must contain "MIT License" and "Permission is hereby granted"
    // Check content length? Original requires substantial? Our short "MIT License text" gave "" (not detected). So require longer? Let's require both phrases and length > 500? The full MIT is 1069 bytes. Short 17 bytes not detected. What about medium? Let's require "MIT License" + "Permission is hereby granted" + "without restriction" + length>200?
