    if content.contains("MIT License") && content.contains("Permission is hereby granted") {
        // additional check: contains "without restriction" or "THE SOFTWARE IS PROVIDED" or length>500?
        if content.len() > 500 || content.contains("without restriction") {
            return Some("MIT".to_string());
        } else {
