fn get_license(repo: &Path) -> String {
    let (cargo_opt, npm_opt) = get_manifests(repo);
    // Cargo license takes precedence if valid and non-empty?
    let cargo_valid = cargo_opt.is_some();
    if let Some((_, _, lic, _)) = &cargo_opt {
        if !lic.is_empty() {
            return lic.clone();
        }
    }
    // If cargo valid (even without license), ignore npm, go to files? As per earlier: cargo valid no lic + npm lic + file => file wins (npm ignored). Good.
    if cargo_valid {
        // check files
    } else {
        // check npm
        if let Some((_, _, lic, _)) = &npm_opt {
            if !lic.is_empty() {
                return lic.clone();
            }
        }
    }
    // files: LICENSE*, LICENCE*, COPYING* in root, sorted?
    let mut candidates: Vec<PathBuf> = vec![];
    if let Ok(entries) = std::fs::read_dir(repo) {
        for e in entries.flatten() {
            let fname = e.file_name().to_string_lossy().to_string();
            if fname.starts_with("LICENSE") || fname.starts_with("LICENCE") || fname.starts_with("COPYING") {
                // must be file, not dir?
                if e.path().is_file() {
                    candidates.push(e.path());
                }
            }
        }
    }
    candidates.sort();
    for p in candidates {
        if let Ok(content) = std::fs::read_to_string(&p) {
            if let Some(lic) = detect_license_text(&content) {
                return lic;
            }
        }
    }
    String::new()
}

