fn get_created_lastchange(repo: &Path, iso: bool) -> (String, String) {
    let all = get_all_commits(repo);
    if all.is_empty() {
        return ("".to_string(), "".to_string());
    }
    // all is newest first (HEAD first). Lastchange = newest (first), created = oldest (last).
    let newest = all[0].timestamp;
    let oldest = all[all.len()-1].timestamp;
    if iso {
        // format as UTC ISO8601: YYYY-MM-DDTHH:MM:SSZ
        use chrono::{TimeZone, Utc};
        let c = Utc.timestamp_opt(oldest, 0).single().map(|d| d.format("%Y-%m-%dT%H:%M:%SZ").to_string()).unwrap_or_default();
        let l = Utc.timestamp_opt(newest, 0).single().map(|d| d.format("%Y-%m-%dT%H:%M:%SZ").to_string()).unwrap_or_default();
        (c, l)
    } else {
        (humanize_time(oldest), humanize_time(newest))
    }
}

fn get_url(repo: &Path, http_url: bool, hide_token: bool) -> String {
    // get origin URL? Or first remote? Use origin if exists, else first.
    let remotes = run_git_stdout(&["remote"], repo).unwrap_or_default();
    let list: Vec<String> = remotes.lines().map(|s| s.trim().to_string()).filter(|s| !s.is_empty()).collect();
    let mut url = String::new();
    if list.contains(&"origin".to_string()) {
        if let Some(u) = run_git_stdout(&["remote", "get-url", "origin"], repo) {
            url = u.trim().to_string();
        }
    } else if !list.is_empty() {
        if let Some(u) = run_git_stdout(&["remote", "get-url", &list[0]], repo) {
            url = u.trim().to_string();
        }
    }
    if url.is_empty() {
        return String::new();
    }
    if hide_token {
        // remove userinfo (token) from https URL: https://token@host/... => https://host/...
        // Also https://user:pass@host/... => https://host/...
        // Use url crate? Parse and clear username/password? But need to preserve original format (e.g., no trailing slash changes)? Original for https://mytoken123@github.com/user/repo.git with --hide-token gives https://github.com/user/repo.git (removes token). Good.
        // For ssh? No token? Only https? Implement: if url starts with http:// or https://, find '@' before first '/' after "://", remove userinfo.
        if url.starts_with("http://") || url.starts_with("https://") {
            if let Some(scheme_end) = url.find("://") {
                let after = &url[scheme_end+3..];
                if let Some(at_pos) = after.find('@') {
                    if let Some(slash_pos) = after.find('/') {
                        if at_pos < slash_pos {
                            // remove userinfo
                            let host_part = &after[at_pos+1..];
                            url = format!("{}://{}", &url[..scheme_end], host_part);
                        }
                    } else {
                        // no slash, whole after is host with userinfo? e.g., https://token@host => https://host
                        let host_part = &after[at_pos+1..];
                        url = format!("{}://{}", &url[..scheme_end], host_part);
                    }
                }
            }
        }
    }
    if http_url {
        // convert scp-like git@host:path to https://host/path
        // Only for scp-like (contains '@' and ':' and no "://")? e.g., git@github.com:user/repo.git => https://github.com/user/repo.git
        // What about git@gitlab.com:group/proj.git => https://gitlab.com/group/proj.git
        // For ssh://... do not convert (as observed).
        if !url.contains("://") && url.contains('@') && url.contains(':') {
            // scp-like: [user@]host:path
            // split at '@' to get host, then at ':' to get path
            if let Some(at_pos) = url.find('@') {
                let after_at = &url[at_pos+1..];
                if let Some(colon_pos) = after_at.find(':') {
                    let host = &after_at[..colon_pos];
                    let path = &after_at[colon_pos+1..];
                    url = format!("https://{}/{}", host, path);
                }
            }
        }
    }
    url
}

