fn detect_language(path: &Path) -> Option<LangDef> {
    let defs = get_lang_defs();
    // map by filename first (Makefile, Dockerfile, CMakeLists.txt, etc.)
    if let Some(fname) = path.file_name().and_then(|s| s.to_str()) {
        if fname == "Makefile" || fname == "makefile" || fname == "GNUmakefile" {
            return defs.iter().find(|d| d.json_name=="Makefile").cloned();
        }
        if fname == "Dockerfile" || fname.to_lowercase().ends_with(".dockerfile") || fname.to_lowercase().starts_with("dockerfile.") {
            return defs.iter().find(|d| d.json_name=="Dockerfile").cloned();
        }
        if fname == "CMakeLists.txt" {
            return defs.iter().find(|d| d.json_name=="CMake").cloned();
        }
        // exact filenames for others? e.g., package.json => Json, Cargo.toml => Toml (but those are also via ext)
        // For .py etc., use extension
    }
    // by extension (lowercase)
    let ext = path.extension().and_then(|s| s.to_str()).map(|s| s.to_lowercase()).unwrap_or_default();
    // special: no extension? e.g., LICENSE => None (Plain Text, excluded)
    if ext.is_empty() {
        return None;
    }
    // .txt, .text => Plain Text => None (excluded)
    if ext == "txt" || ext == "text" {
        return None;
    }
    // headers .h, .hpp, .hh, .hxx => None (as observed, ignored)
    if ext == "h" || ext == "hpp" || ext == "hh" || ext == "hxx" || ext == "h++" {
        return None;
    }
    // csv, gitignore, etc. => None
    if ext == "csv" || ext == "gitignore" {
        return None;
    }
    let map: HashMap<&str, &str> = [
        ("py", "Python"), ("rs", "Rust"), ("js", "JavaScript"), ("cjs", "JavaScript"), ("mjs", "JavaScript"),
        ("jsx", "Jsx"), ("ts", "TypeScript"), ("tsx", "Tsx"), ("c", "C"),
        ("cpp", "Cpp"), ("cc", "Cpp"), ("cxx", "Cpp"), ("c++", "Cpp"),
        ("java", "Java"), ("go", "Go"), ("rb", "Ruby"), ("php", "Php"),
        ("sh", "Sh"), ("bash", "Bash"), ("zsh", "Zsh"), ("fish", "Fish"),
        ("html", "Html"), ("htm", "Html"), ("css", "Css"), ("scss", "Sass"), ("sass", "Sass"),
        ("xml", "Xml"), ("svg", "Svg"), ("vue", "Vue"), ("svelte", "Svelte"),
        ("md", "Markdown"), ("markdown", "Markdown"), ("org", "Org"), ("tex", "Tex"),
        ("json", "Json"), ("yaml", "Yaml"), ("yml", "Yaml"), ("toml", "Toml"),
        ("kt", "Kotlin"), ("kts", "Kotlin"), ("swift", "Swift"), ("scala", "Scala"), ("sc", "Scala"),
        ("hs", "Haskell"), ("lua", "Lua"), ("pl", "Perl"), ("pm", "Perl"), ("r", "R"),
        ("m", "ObjectiveC"), ("cs", "CSharp"), ("fs", "FSharp"), ("fsi", "FSharp"), ("fsx", "FSharp"),
        ("sql", "Sql"), ("cmake", "CMake"), ("dockerfile", "Dockerfile"),
        ("make", "Makefile"), ("mk", "Makefile"),
        ("clj", "Clojure"), ("cljs", "Clojure"), ("ex", "Elixir"), ("exs", "Elixir"),
        ("erl", "Erlang"), ("hrl", "Erlang"), ("dart", "Dart"), ("jl", "Julia"),
    ].iter().cloned().collect();
    if let Some(json) = map.get(ext.as_str()) {
        return defs.iter().find(|d| &d.json_name == json).cloned();
    }
    // Try more: .cjs, .mjs already, .ts already, etc.
    // For unknown, None
    None
}

fn count_loc(content: &[u8], def: &LangDef) -> usize {
    // check binary: contains null byte?
    if content.contains(&0) {
        return 0;
    }
    let text = match std::str::from_utf8(content) {
        Ok(s) => s,
        Err(_) => return 0,
    };
    let mut count = 0usize;
    let mut in_block = false;
    let block_start = def.block_start.unwrap_or("");
    let block_end = def.block_end.unwrap_or("");
    for raw_line in text.lines() {
        let line = raw_line;
        if in_block {
            // look for block_end
            if let Some(pos) = line.find(block_end) {
                in_block = false;
                let after = &line[pos+block_end.len()..];
                // check if after contains code (non-space, not line comment, not another block?)
                // Simplify: trim after, if non-empty and not starting with line comment, and not empty, then count as code? But need to handle line comments after block?
                // For simplicity, if after.trim().is_empty() => not code, else check if after.trim_start() starts with line comment => not code, else code.
                let t = after.trim();
                if t.is_empty() {
                    continue;
                }
                let mut is_comment = false;
                for lc in &def.line_comments {
                    if t.starts_with(lc) {
                        is_comment = true;
                        break;
                    }
                }
                // also check if after contains another block_start? Ignore for simplicity (rare).
                if !is_comment {
                    // check if after is just block_end? Already consumed. If after has code, count.
                    count += 1;
                }
            } else {
                // still in block, not code
                continue;
            }
        } else {
            let trimmed = line.trim();
            if trimmed.is_empty() {
                continue;
            }
            // check line comments: if trimmed starts with any line_comment => not code
            let mut starts_with_line = false;
            for lc in &def.line_comments {
                if trimmed.starts_with(lc) {
                    starts_with_line = true;
                    break;
                }
            }
            if starts_with_line {
                continue;
            }
            // check block comments
            if let (Some(bs), Some(be)) = (def.block_start, def.block_end) {
                if let Some(start_pos) = line.find(bs) {
                    // find line comment before block? If line comment appears before block_start, then check prefix before line comment for code?
                    // Find earliest line comment pos
                    let mut earliest_lc: Option<usize> = None;
                    for lc in &def.line_comments {
                        if let Some(p) = line.find(lc) {
                            if earliest_lc.map_or(true, |e| p < e) {
                                earliest_lc = Some(p);
                            }
                        }
                    }
                    if let Some(lc_pos) = earliest_lc {
                        if lc_pos < start_pos {
                            // line comment before block: check prefix before lc for code
                            let before = line[..lc_pos].trim();
                            if !before.is_empty() {
                                count += 1;
                            }
                            continue;
                        }
                    }
                    // block starts: check prefix before block for code?
                    let before = line[..start_pos].trim();
                    let has_code_before = !before.is_empty();
                    // check if block ends on same line
                    if let Some(end_rel) = line[start_pos+bs.len()..].find(be) {
                        // ends same line: check after for code? If before has code, count. Else check after.
                        if has_code_before {
                            count += 1;
                        } else {
                            let after_start = start_pos+bs.len()+end_rel+be.len();
                            let after = line[after_start..].trim();
                            if after.is_empty() {
                                // only block on line, no code
                                continue;
                            }
                            // check if after starts with line comment?
                            let mut after_is_comment = false;
                            for lc in &def.line_comments {
                                if after.starts_with(lc) {
                                    after_is_comment = true;
                                    break;
                                }
                            }
                            if !after_is_comment {
                                count += 1;
                            }
                        }
                    } else {
                        // block continues to next lines
                        if has_code_before {
                            count += 1;
                        } else {
                            // no code before, start block, not code for this line
                        }
                        in_block = true;
                    }
                    continue;
                }
            }
            // check inline line comment? e.g., "x=1 # comment" => has code before, count. Our earlier check for starts_with would not catch inline, so need to check: if line contains line comment, but prefix has code, count.
            // Actually for lines not starting with comment, but containing comment later, they are code (since prefix non-empty). Our current logic: if not starting with comment and no block, count as code. Good: covers inline.
            // But need to handle: line like "   # comment with leading spaces" already handled via trimmed starts_with. Good.
            count += 1;
        }
    }
    count
}

fn get_languages_loc(repo: &Path, excludes: &[String], include_hidden: bool, types: &[String]) -> (Vec<(String, String, String, usize)>, usize) {
    // returns Vec of (json_name, display_name, ascii_slug, loc) and total_loc, filtered by types, sorted by loc desc then? (original non-deterministic for ties, we sort by loc desc then json_name asc for determinism)
    use ignore::{WalkBuilder, overrides::OverrideBuilder};
    let mut builder = WalkBuilder::new(repo);
    builder.hidden(!include_hidden);
    builder.git_ignore(true);
    builder.git_global(false);
    builder.git_exclude(true);
    builder.require_git(false);
    builder.parents(false);
    // Always skip .git even with include_hidden
    let mut over_builder = OverrideBuilder::new(repo);
    // Exclude .git dir: add "! .git"? Actually Override with "!*.git"? Simpler: filter in loop (skip paths containing .git).
    // For excludes, we handle manually via should_exclude (since ignore's override uses different glob semantics? Our should_exclude matches observed behavior (basename + rel_path). Use manual.
    builder.follow_links(false);
    builder.standard_filters(false); // we handle hidden/gitignore manually? Actually standard_filters includes hidden? Let's use custom: hidden as above, git_ignore true.
    // To avoid issues, use WalkBuilder with hidden, git_ignore, etc., and filter .git manually.
    let walker = builder.build();
    let mut counts: HashMap<String, (String, String, String, usize)> = HashMap::new(); // json_name -> (json, display, ascii, loc)
    // Need type filter: set of allowed types
    let allowed: HashSet<String> = types.iter().cloned().collect();
    for entry in walker.flatten() {
        let path = entry.path();
        // skip .git dir
        if path.components().any(|c| c.as_os_str() == ".git") {
            continue;
        }
        // skip dirs (only files)
        if path.is_dir() {
            continue;
        }
        // skip symlinks? ignore crate with follow_links false will still list symlink files? Check if symlink, skip for LOC (as observed, symlink not counted).
        if entry.file_type().map(|t| t.is_symlink()).unwrap_or(false) {
            continue;
        }
        // Also skip if path is symlink via symlink_metadata?
        if let Ok(md) = std::fs::symlink_metadata(path) {
            if md.file_type().is_symlink() {
                continue;
            }
        }
        // rel path for excludes
        let rel = path.strip_prefix(repo).unwrap_or(path).to_string_lossy().to_string();
        // normalize to forward slashes? On Linux, already /. Good.
        let basename = path.file_name().and_then(|s| s.to_str()).unwrap_or("").to_string();
        // hidden check already via WalkBuilder? But WalkBuilder hidden(false) skips hidden files/dirs? With include_hidden false, it skips hidden. With true, includes. Good. But need to ensure .git skipped even when true (we did above).
        // excludes
        if should_exclude(&rel, &basename, excludes) {
            continue;
        }
        // detect language
        if let Some(def) = detect_language(path) {
            // type filter
            if !allowed.contains(def.lang_type) {
                continue;
            }
            // read file, count loc
            if let Ok(content) = std::fs::read(path) {
                let loc = count_loc(&content, &def);
                if loc == 0 {
                    continue;
                }
                let entry = counts.entry(def.json_name.to_string()).or_insert((def.json_name.to_string(), def.display_name.to_string(), def.ascii_slug.to_string(), 0));
                entry.3 += loc;
            }
        }
    }
    let mut vec: Vec<(String,String,String,usize)> = counts.into_values().collect();
    // sort by loc desc, then json_name asc (deterministic)
    vec.sort_by(|a,b| b.3.cmp(&a.3).then_with(|| a.0.cmp(&b.0)));
    let total: usize = vec.iter().map(|(_,_,_,c)| c).sum();
    (vec, total)
}

