    }
}

fn parse_truecolors() -> HashMap<String, (String, Option<(u8,u8,u8)>)> {
    // returns slug -> (ansi_code_without_bold? e.g., "34" or "39", rgb_opt)
    let content = include_str!("../assets/truecolors.txt");
    let mut map = HashMap::new();
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() { continue; }
        // format: "<slug>  never=<code> always=<code> auto=<code> rgb=<bool>"
        // e.g., "python  never=34;1 always=38;2;47;105;162;1 auto=34;1 rgb=True"
        // Split by whitespace?
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() < 2 { continue; }
        let slug = parts[0].to_string();
        let mut never_code = String::new();
        let mut always_code = String::new();
        for p in &parts[1..] {
            if p.starts_with("never=") {
                never_code = p["never=".len()..].to_string();
            } else if p.starts_with("always=") {
                always_code = p["always=".len()..].to_string();
            }
        }
        // never_code like "34;1" or "39;1" or "36;1" etc. Extract base "34" or "39" (before ;).
        let ansi_base = never_code.split(';').next().unwrap_or("39").to_string();
        // always_code like "38;2;47;105;162;1" or "34;1" etc. If starts with "38;2;", parse RGB, else None (no true-color, use ANSI).
        let rgb_opt = if always_code.starts_with("38;2;") {
            // format 38;2;R;G;B;1 or 38;2;R;G;B (without ;1? Actually always has ;1? For true-color, always ends with ;1? Yes "38;2;...;1". Good.
            let nums: Vec<&str> = always_code.split(';').collect();
            // ["38","2","R","G","B","1"] or ["38","2","R","G","B"]?
            if nums.len() >= 5 {
                if let (Ok(r), Ok(g), Ok(b)) = (nums[2].parse::<u8>(), nums[3].parse::<u8>(), nums[4].parse::<u8>()) {
